<dialog id="product-{{ $item->id??'new' }}" class="editor-dialog"><div class="dialog-heading"><h2>{{ $item?'Edit product':'A new little blend' }}</h2><button data-close aria-label="Close product editor">×</button></div><form action="/admin/products{{ $item?'/'.$item->id:'' }}" method="post" enctype="multipart/form-data" class="dialog-content">@csrf<div class="form-grid">@foreach(['name'=>'Product name','sku'=>'SKU','category'=>'Category','weight'=>'Pack size','price'=>'Price in INR','stock'=>'Available stock'] as $key=>$label)<label>{{ $label }}<input name="{{ $key }}" value="{{ $key==='price'?($item?number_format($item->price/100,2,'.',''):''):($item->$key??'') }}" type="{{ in_array($key,['price','stock'])?'number':'text' }}" @if($key==='price') min="1" step="0.01" @elseif($key==='stock') min="0" step="1" @endif required></label>@endforeach @foreach(['description'=>'Description','ingredients'=>'Ingredients','allergens'=>'Allergen information'] as $key=>$label)<label class="full">{{ $label }}<textarea name="{{ $key }}" rows="3" @required($key==='description')>{{ $item->$key??'' }}</textarea></label>@endforeach<label>Placeholder pack colour<select name="colour">@foreach(['orange','blue','green','lilac'] as $colour)<option @selected(($item->colour??'orange')===$colour)>{{ $colour }}</option>@endforeach</select></label><label>Product image<input type="file" name="image" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP. Up to 2 MB.</small></label><label class="checkbox full"><input type="checkbox" name="active" value="1" @checked($item->active??true)> Published on website</label></div><button class="button button-blue">Save product</button></form>@if($item&&$item->active)<form action="/admin/archive/products/{{ $item->id }}" method="post" class="dialog-archive">@csrf<button class="text-link" data-confirm="Archive this product? It will be hidden from the store.">Archive product</button></form>@endif</dialog>
